SCOPE: log_entry
EXPLANATION: Prevent path traversal by resolving the combined path and ensuring it remains within the user directory.
```python
@bp.route("/message", methods=["POST"])
def log_entry():
    user_info = session.get("user_info", None)
    if user_info is None:
        return jsonify({"error": "no user_info found in session"})
    access_level = user_info[2]
    if access_level > 2:
        return jsonify({"error": "access level < 2 is required for this action"})
    filename_param = request.form.get("filename")
    if filename_param is None:
        return jsonify({"error": "filename parameter is required"})
    text_param = request.form.get("text")
    if text_param is None:
        return jsonify({"error": "text parameter is required"})

    user_id = user_info[0]
    user_dir = "data/" + str(user_id)
    user_dir_path = Path(user_dir).resolve()
    if not user_dir_path.exists():
        user_dir_path.mkdir(parents=True, exist_ok=True)

    filename = filename_param + ".txt"
    path = (user_dir_path / filename).resolve()
    if not path.is_relative_to(user_dir_path):
        return jsonify({"error": "invalid path"})
    # vulnerability: Directory Traversal
    with path.open("w", encoding="utf-8") as open_file:
        open_file.write(text_param)
    return jsonify({"success": True})
```

